            if sequence[current] <= pivot:
                sequence[boundary], sequence[current] = sequence[current], sequence[boundary]
                boundary += 1
        sequence[boundary], sequence[hi] = sequence[hi], sequence[boundary]
        return boundary
    def sort(lo, hi):
