        for j in range(start, end):
            if output[j] < pivot:
                output[i], output[j] = output[j], output[i]
                i += 1
        output[i], output[end] = output[end], output[i]
        divide(start, i - 1)
        divide(i + 1, end)
    divide(0, len(output) - 1)
    return output

def recursive_find(array, value, lo, hi):
    if lo > hi:
        return -1
    center = (lo + hi) // 2
    if array[center] == value:
        return center
    if value < array[center]:
        return recursive_find(array, value, lo, center - 1)
    return recursive_find(array, value, center + 1, hi)

