def bubble_order(seq):
    copy = list(seq)
    n = len(copy)
    while n > 1:
        new_n = 0
        for i in range(1, n):
            if copy[i - 1] > copy[i]:
                copy[i - 1], copy[i] = copy[i], copy[i - 1]
                new_n = i
        n = new_n
    return copy

